text:
{
  "units": [
    {
      "issue": "截至2023-08-01、不计当日利息，三笔虚构借款关系分别可支持的债务项目、金额计算基础及丁、戊、己的保证责任状态，并据此确定对乙的请求总额与可立即请求保证人支付的范围。",
      "decisive_facts": [
        {
          "id": "F0",
          "fact": "全部案件资料为显著虚构题设，不是法院认定；除明确的单方主张外，事实无争议。结算截止日为2023-08-01，不计当日利息，不存在未列明付款、其他无效事由或法律例外。",
          "spans": ["normalized_text:导语"]
        },
        {
          "id": "F1",
          "fact": "A资金来源为套取的银行信贷资金；实际交付142851.00元，票面160000元。乙不知资金来源、约定年利率6%，均为题设事实。",
          "spans": ["S01"]
        },
        {
          "id": "F2",
          "fact": "A已返还19939.00元，双方约定全部冲抵无效清算中的财产返还；甲仅请求剩余实际交付财产，不请求票面差额或其他赔偿。丁的保证方式约定为连带责任保证。",
          "spans": ["S01", "S02", "S12"]
        },
        {
          "id": "F3",
          "fact": "B为合法自有资金借款，最初借据日期为2022-01-12；票面193197.00元包含预扣利息12087.00元，实际收到181110.00元。约定年利率13.200%，题设确认合同成立时一年期LPR为3.70%。实际交付的具体日期未被单独明确记载。",
          "spans": ["S03"]
        },
        {
          "id": "F4",
          "fact": "B于2022-07-06、2023-01-09重新出具结息借据，均无新增现金、债务更新或独立费用；纸面本金未经法律审查。各期使用相同约定利率和最初合同成立时LPR，实际自然日计息、年基数365，B没有另行还款。",
          "spans": ["S04", "S05", "S11"]
        },
        {
          "id": "F5",
          "fact": "戊书面提供B的连带责任保证，未约定保证期间，已书面同意合法结息机制及相应保证范围。原履行期限为2023-01-12；展期至2023-06-30未经戊书面同意。首次要求戊承担保证责任的通知于2023-07-05到达。",
          "spans": ["S06"]
        },
        {
          "id": "F6",
          "fact": "C于2022-02-07实际交付221230.00元，2022-12-15到期，借期内与逾期年利率均为11.40%，题设LPR为3.70%。依法可收取的费用1680元在四笔付款前已到期；按未清偿本金单利计息，不对未付利息计息。",
          "spans": ["S07"]
        },
        {
          "id": "F7",
          "fact": "C四笔实际结算付款分别为2022-04-18的9839.00元、2022-08-23的11570.00元、2022-11-14的13301.00元、2023-02-21的15032.00元，均指定清偿C；不存在另行清偿顺序约定。",
          "spans": ["S08", "S09"]
        },
        {
          "id": "F8",
          "fact": "己的保证合同未约定保证方式及保证期间。甲于2023-05-08向己发送支付请求短信，于2023-06-20才对乙提起关于C的独立诉讼。前诉尚未审判，乙有可执行财产，无先诉抗辩例外，己未放弃该抗辩。",
          "spans": ["S10"]
        },
        {
          "id": "F9",
          "fact": "重复出现的T-01截图和收据均对应同一交易；X-01失败未结算、没有实际到账。A收据不是追加交付，B新借据不是新现金。最终各输出分项取分后再相加，不跨债务冲抵，不另行计算保证合同无效后的过错赔偿。",
          "spans": ["S11", "S12"]
        }
      ],
      "support_spans": [
        {
          "type": "material",
          "span_id": "normalized_text:导语",
          "locator_note": "原文导语没有编号，此处为描述性定位，不新增原始span_id。",
          "excerpt": "这是法律数据合成研究构造的闭卷情景，不是真实诉讼、证据或判决。"
        },
        {
          "type": "material",
          "span_ids": ["S01", "S02"],
          "excerpts": [
            "甲把为个人消费用途向银行套取的信贷资金转给乙",
            "双方认可在本次无效清算中全部作为已返还财产冲抵"
          ]
        },
        {
          "type": "material",
          "span_ids": ["S03", "S04", "S05"],
          "excerpts": [
            "B最初借据日期2022-01-12",
            "乙实际收到181110.00元",
            "纸面数是当事人名义记账，未经法定利率与本金审查",
            "均没有新现金交付"
          ]
        },
        {
          "type": "material",
          "span_id": "S06",
          "excerpts": [
            "唯该展期戊没有书面同意",
            "甲首次向戊要求承担保证责任并到达戊的日期是2023-07-05"
          ]
        },
        {
          "type": "material",
          "span_ids": ["S07", "S08", "S09"],
          "excerpts": [
            "利息以当时未清偿本金、实际自然日/365单利累计",
            "乙指定偿还C号债务",
            "C所有各笔均无另行清偿顺序约定"
          ]
        },
        {
          "type": "material",
          "span_id": "S10",
          "excerpts": [
            "未写保证方式且未约定保证期间",
            "甲另于2023-06-20对乙提起关于C的独立诉讼",
            "截至截日该前诉未审判"
          ]
        },
        {
          "type": "material",
          "span_ids": ["S11", "S12"],
          "excerpts": [
            "以上文件未新增与主表不同的实际支付",
            "各输出分项最终取分后再相加形成总额，不作不同债务交叉冲抵"
          ]
        },
        {
          "type": "rule",
          "source_id": "lending-2020-12",
          "provisions": ["13", "25", "26", "27", "28", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "version_basis": "材料载明自2021-01-01施行；本单元按题设交易及受理时点适用，不作当前法律效力声明。"
        },
        {
          "type": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["157", "560", "561", "670", "679", "682", "686", "687", "688", "691", "692", "693", "695", "1260"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "version_basis": "材料载明自2021-01-01施行；引用依据为本次提供的条文摘录。"
        }
      ],
      "dependencies": {
        "nodes": [
          {
            "id": "N0",
            "label": "适用版本",
            "depends_on": [],
            "fact_refs": ["F0", "F1", "F3", "F6"],
            "rule_refs": ["lending-2020-12:31", "civil-code-2020:1260"],
            "supported_state": "按题设时点使用2020年12月修正的民间借贷司法解释及民法典，不将2015年规则中的高利转贷、借款人知情要件移用于本情景。"
          },
          {
            "id": "N1",
            "label": "交付与付款的真实性、唯一性及债务归属",
            "depends_on": [],
            "fact_refs": ["F2", "F3", "F4", "F7", "F9"],
            "rule_refs": ["civil-code-2020:560"],
            "supported_state": "A收据、B结息借据不增加实际交付；T-01仅计一次；X-01不计入付款；四笔已结算付款均归入C，不冲抵A或B。"
          },
          {
            "id": "N2",
            "label": "A主合同效力",
            "depends_on": ["N0"],
            "fact_refs": ["F1"],
            "rule_refs": ["lending-2020-12:13"],
            "supported_state": "题设资金来源满足套取金融机构贷款转贷的无效情形；乙不知来源及6%利率不排除该无效事由。"
          },
          {
            "id": "N3",
            "label": "A财产返还范围",
            "depends_on": ["N1", "N2"],
            "fact_refs": ["F1", "F2"],
            "rule_refs": ["civil-code-2020:157"],
            "supported_state": "请求性质为无效后的剩余实际交付财产返还，不是按票面本金履行有效借款合同。",
            "calculation_spec": "A返还额＝142851.00－19939.00；不计入未交付票面差额、重复收据或题设排除的赔偿。"
          },
          {
            "id": "N4",
            "label": "丁的保证状态",
            "depends_on": ["N2"],
            "fact_refs": ["F2", "F9"],
            "rule_refs": ["civil-code-2020:682"],
            "supported_state": "主合同无效且无题设法律例外，丁的保证合同随之无效。不得把乙的财产返还额直接填作丁的连带保证债务；过错赔偿不在本单元范围内。"
          },
          {
            "id": "N5",
            "label": "B成立、初始本金及初段起算",
            "depends_on": ["N0", "N1"],
            "fact_refs": ["F3"],
            "rule_refs": ["civil-code-2020:679", "civil-code-2020:670", "lending-2020-12:26"],
            "supported_state": "B已实际交付，初始本金为181110.00元，预扣的12087.00元不能作为本金或已另行支付的利息重复计入。",
            "unresolved": "S03明确记载借据日期，但未明确实际交付日期；不能在严格依据题设的精确金额标签中默认为同一天。"
          },
          {
            "id": "N6",
            "label": "B逐期结息本金审查",
            "depends_on": ["N5"],
            "fact_refs": ["F3", "F4"],
            "rule_refs": ["lending-2020-12:25", "lending-2020-12:27"],
            "supported_state": "四倍LPR上限为14.80%，约定13.200%未超过该上限。但必须以合法初始本金逐期重建可计入后期本金的利息，不能直接承认两份纸面本金，也不能因没有新现金而一概否认合法结息。",
            "calculation_spec": "合法期末结息本金＝该期合法期初本金＋按约定利率及确定日数计算、依法允许计入的未付利息；中间过程保留精度。",
            "unresolved": "第一期实际计息起点待明确，影响后续全部结息本金。"
          },
          {
            "id": "N7",
            "label": "B最终本息及整体上限",
            "depends_on": ["N6"],
            "fact_refs": ["F3", "F4", "F5", "F9"],
            "rule_refs": ["lending-2020-12:27", "lending-2020-12:28"],
            "supported_state": "逐期结息通过不等于最终本息当然全部受保护；还须审查以最初合法本金和四倍LPR计算的整个期间本息上限。B未另列逾期利率，可按所给第28条审查借期内约定利率在逾期资金占用期间的适用。",
            "calculation_spec": "将重建后的截至截日本息，与以181110.00元为最初本金、14.80%为上限利率计算的整体限额比较；不预设整体限额必然实际截减金额，不另加纸面本金或预扣利息。"
          },
          {
            "id": "N8",
            "label": "戊的保证期间、行权及支付范围",
            "depends_on": ["N0", "N7"],
            "fact_refs": ["F5"],
            "rule_refs": ["civil-code-2020:688", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:695"],
            "supported_state": "未经戊书面同意的展期不改变保证期间。按原到期日2023-01-12起算六个月，期间届满日为2023-07-12；2023-07-05到达的请求在期间内。B展期后的债务亦已到期，可请求戊在原保证约定及依法保护的债务范围内承担连带支付责任。",
            "scope_constraint": "已书面同意的合法结息部分不因无新现金而当然排除；不得计入不受保护金额或未经同意新增的负担。具体保证金额依赖N7。"
          },
          {
            "id": "N9",
            "label": "C利率、债务指定与内部清偿顺序",
            "depends_on": ["N0", "N1"],
            "fact_refs": ["F6", "F7"],
            "rule_refs": ["civil-code-2020:560", "civil-code-2020:561", "lending-2020-12:25", "lending-2020-12:28"],
            "supported_state": "11.40%低于14.80%的题设上限。指定偿还C只决定债务归属，不等于指定先还本金；因没有另行约定，C内部依次清偿已到期费用、利息、本金。"
          },
          {
            "id": "N10",
            "label": "C逐笔清偿与剩余金额",
            "depends_on": ["N9"],
            "fact_refs": ["F6", "F7", "F9"],
            "rule_refs": ["civil-code-2020:561"],
            "supported_state": "每笔付款对本金的实际清偿额改变下一段计息基数；重复凭证和失败指令不得降低余额。",
            "calculation_spec": [
              "从2022-02-07起，按各段期初未偿本金、11.40%及实际自然日/365累计单利。",
              "每笔实际付款依次冲抵未偿费用、已生利息及本金，并更新余额；不得先将四笔付款合并后直接扣本金。",
              "付款当日被偿还本金不再计息，剩余本金继续计息至2023-08-01之前；未付利息不资本化。",
              "分别形成截至截日的未偿本金、合法利息和未偿费用。"
            ]
          },
          {
            "id": "N11",
            "label": "己的保证方式、期间及有效行权",
            "depends_on": ["N0"],
            "fact_refs": ["F6", "F8"],
            "rule_refs": ["civil-code-2020:686", "civil-code-2020:692", "civil-code-2020:693"],
            "supported_state": "未约定保证方式，应按一般保证处理。C于2022-12-15到期，未约定的保证期间为六个月，届满日为2023-06-15。2023-05-08向己发短信不替代一般保证所要求的对债务人起诉或申请仲裁；2023-06-20起诉已经超过保证期间，因此己不再承担保证责任。"
          },
          {
            "id": "N12",
            "label": "己是否属于已保全但暂可拒绝支付",
            "depends_on": ["N11"],
            "fact_refs": ["F8"],
            "rule_refs": ["civil-code-2020:687", "civil-code-2020:693"],
            "supported_state": "当前材料不能将己归入“期间内有效保全但尚可行使先诉抗辩”。前诉未审判等事实虽与先诉抗辩有关，但不能补救已经超过保证期间的行权，也不能恢复已经免除的保证责任。"
          },
          {
            "id": "N13",
            "label": "最终请求项目及责任状态汇总",
            "depends_on": ["N3", "N4", "N7", "N8", "N10", "N11", "N12"],
            "fact_refs": ["F9"],
            "supported_state": "对乙的总额由A剩余财产返还、B可保护本息及C剩余各项债务构成。丁属于保证合同无效，戊属于可请求连带支付，己属于保证期间届满后不再承担保证责任。本题没有“期间内有效保全但尚可行使先诉抗辩”的保证人。",
            "calculation_spec": "按S12确定各输出分项，最终取分后相加；保证责任不作为另一笔债权叠加进对乙的债务总额，不跨债务冲抵。"
          }
        ],
        "terminal_node": "N13",
        "necessary_interactions": [
          {
            "nodes": ["N5", "N6", "N7", "N8"],
            "effect": "实际出借本金及初段计息时间影响合法结息、整体限额比较，进而影响B债务及戊可承担的保证金额。"
          },
          {
            "nodes": ["N1", "N9", "N10"],
            "effect": "付款是否真实且唯一、所指定的债务及内部清偿顺序共同决定C剩余本金和后续利息。"
          },
          {
            "nodes": ["N2", "N3", "N4"],
            "effect": "A主合同效力同时改变对乙请求的法律性质和丁的保证合同效力。"
          },
          {
            "nodes": ["N11", "N12"],
            "effect": "一般保证的行权方式与六个月期限共同决定责任是否保留；不能仅因存在前诉而跳到先诉抗辩判断。"
          }
        ]
      },
      "answerability": {
        "status": "partial",
        "supported_scope": [
          "A的无效、财产返还范围及丁的保证合同无效状态。",
          "B初始合法本金、逐期结息和整体上限的适用结构。",
          "戊的保证期间及期间内有效请求状态。",
          "C的付款归属、清偿顺序及金额计算结构。",
          "己的一般保证及保证期间届满免除状态。",
          "不得强行为四种保证状态各安排一名保证人。"
        ],
        "blockers": [
          {
            "field": "B.initial_disbursement_date_and_first_accrual_start",
            "reason": "S03只明确最初借据日期及实际收到金额，没有明确实际交付日期；S04也未单独确定第一期计息起点。仅凭借据日期生成唯一精确本息，存在补入题设未明示事实的风险。",
            "required_resolution": "补明B实际交付日期和第一期计息起点；若均为2022-01-12，应显式确认。",
            "affected_outputs": [
              "B各次合法结息本金",
              "B截至截日的可保护本息",
              "戊的具体保证金额",
              "对乙的最终请求总额"
            ]
          }
        ],
        "generation_gate": "可保留上述有据状态与依赖图；在B初段起算事实明确前，不生成要求唯一精确总额的完整主问题。",
        "validation_status": "仅完成P1提取；未进行十进制定点复算、独立盲答或发布验收。"
      }
    }
  ],
  "rejected_units": [],
  "limitations": [
    "所有事实状态均来自虚构题设，法律结论仅为对所给事实及规范的适用分析，不是法院实际判断或裁判提取标签。",
    "来源元数据所列verification、哈希及检索时间未在本次独立核验；公开链接用于追溯依据，不代表已重新访问或核验官方原文。",
    "材料机制标签不能替代具体事实。当前S09明确没有清偿顺序例外约定，不支持把C包装为存在约定例外的情景。",
    "S10明确的起诉日期晚于C保证期间届满日，不支持“期间内有效保全”的状态；S12要求区分四类状态，并不证明本情景四类均有实例。",
    "B逐期利率低于四倍LPR，不代表免于整体本息上限审查，也不证明该整体上限必然实际触发。",
    "B起算事实的局部缺口应作为可回答性问题处理，不作为难度证据；不得以默填日期或继承原案答案消除。"
  ]
}
